def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    return float(v) if v is not None and math.isfinite(v) and v > 0 else 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x * r ** 3
            weight += x
    return float(4.0 * math.pi * total / (3.0 * weight * v)) if weight > 0 else 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and z is not None and math.isfinite(z):
            total += x * z
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    q = [max(0.0, float(a.get('occupancy', 1.0) or 0.0)) for a in sites]
    nearest = [math.inf] * n
    neighbors = s.get('neighbors', ())
    for b in neighbors:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and q[i] > 0 and q[j] > 0 and d < nearest[i]:
            nearest[i] = d
    counts = [0.0] * n
    for b in neighbors:
        i, j = b['i'], b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and d <= 1.25 * nearest[i] and q[i] > 0 and q[j] > 0:
            counts[i] += q[j]
    w = sum(q)
    if w <= 0:
        return 0.0
    mean = sum(q[i] * counts[i] for i in range(n)) / w
    return float(math.sqrt(max(0.0, sum(q[i] * (counts[i] - mean) ** 2 for i in range(n)) / w)))
